update sc_plans set title=$q$Grandma saved one every winter… 🥺$q$, title_ko=$q$어릴 적 할머니는 가장 잘 익은 홍시를 하트 새긴 놋숟가락으로 떠먹여 줬다. 지금, 눈 오는 겨울 할머니는 혼자 장독 위에 홍시 하나를 남겨 두고 대문만 바라본다. 까치가 대문 지붕에 앉아 운다(한국에선 까치가 울면 반가운 손님이 온다). 어른이 된 손녀가 같은 숟가락으로 이번엔 할머니에게 홍시를 떠먹인다.$q$, hook=$q$첫 컷: 할머니가 떠먹여 주는 빨간 홍시와 하트 숟가락 — 왜 이 숟가락이 중요할까?$q$, emotion='grand', korea=$q$한옥 장독대·홍시·까치 울음 속설$q$, outline=$q$[{"scene": "오래전 가을, 마루에서 할머니가 하트 놋숟가락으로 다섯 살 손녀에게 홍시를 떠먹인다", "cap": "She always saved the ripest one for me."}, {"scene": "지금, 눈 오는 겨울. 혼자인 할머니가 장독 위 홍시 하나와 숟가락을 두고 대문을 바라본다", "cap": "Every winter, she kept one. Just in case."}, {"scene": "까치가 대문 지붕에 내려앉아 운다, 할머니가 돌아본다", "cap": "In Korea, a magpie's call means someone is coming."}, {"scene": "마루에서 어른이 된 손녀(빨간 코트)가 같은 숟가락으로 할머니에게 홍시를 떠먹인다", "cap": "This time, I fed her."}]$q$::jsonb, spec=spec || $q${"bible": {"grandma_then": "GRANDMA (years ago): a Korean grandma in her late sixties, black-grey hair in a low bun, round kind face, indigo quilted vest over a cream blouse.", "grandma_now": "GRANDMA (now): the same Korean grandma, now in her eighties, snow-white hair in a low bun, deeper smile wrinkles, the same indigo quilted vest, a little more bent.", "girl": "GIRL (years ago): her granddaughter about five, round face, short black bob with bangs, bright red knit cardigan.", "woman": "WOMAN (now): the same granddaughter grown into a young woman in her late twenties, round face, black bob with bangs, a bright red wool coat.", "spoon": "a small brass spoon with a tiny heart engraved on the handle", "place": "PLACE: a hanok courtyard with a wooden porch (maru), a jangdokdae of round brown earthenware crocks on a stone platform, a wooden gate with a small tiled roof, a persimmon tree."}, "details": [{"prop": "하트 새긴 작은 놋숟가락", "where": [1, 2, 4], "meaning": "같은 숟가락이 세월을 건너 역할이 바뀐다"}, {"prop": "장독 위 홍시 단 하나", "where": [2, 4], "meaning": "해마다 손녀 몫을 남겨 둔 기다림"}, {"prop": "빨간 카디건 → 빨간 코트", "where": [1, 4], "meaning": "같은 아이임을 색으로 알려 준다"}], "format": "grand-role-reversal (세월 뒤 갚기)", "hook_type": "memory-first-frame", "music": "music_classical-7", "pinned": "What did YOUR grandma always save for you? 🥺 Tell Kachi 💛", "description": "When I was little, Grandma saved the ripest persimmon for me.\nEvery winter since, she kept one… just in case.\n\nIn Korea, the magpie is the bird that brings good news 🐦\n\n#Grandma #Korea #Hanok #Persimmon #Family #shorts", "tags": ["grandma", "granddaughter", "persimmon", "hongsi", "hanok", "Korea", "magpie", "miniature animation", "Kachi", "From Korea With Love"], "notes": "10/29 까치밥(감)과 소재가 가깝지만 전제가 다름(새 몫 → 손녀 몫, 역할 반전). 손녀 일관성: 빨간 옷·단발 앞머리, 4컷 ref gh1. 3컷 할머니는 아주 작게 흐리게.", "reuse": [], "followup_of": null, "est_usd": 1.5, "cuts": 4, "p0_scores": {"surprise": 4, "emotion": 5, "natural": 5, "kachi": 4}, "production": {"gen_img": "scripts/side/gen_next/M261101-hongsi-img.json", "gen_vid": "scripts/side/gen_next/M261101-hongsi-vid.json", "render_id": "E261101-hongsi"}, "shots": []}$q$::jsonb, status='approved', updated_at=now(), feedback=feedback || jsonb_build_array($q${"by": "claude", "type": "note", "text": "이전안(반전·까치 역할 약함) P0 미달이라 새로 씀: 하트 놋숟가락 → 장독 위 홍시 하나 기다림 → 까치 울음(손님 온다) → 어른 손녀가 같은 숟가락으로 할머니에게. PLAN-FIRST 촬영표 완성(4컷·엔딩 포함 약 22초·예상 실비 $1.5: 그림 4·영상 4). P0 점수 놀라움 4·감정 5·자연스러움 5·까치 역할 4 → 승인. 생성 작업 파일: scripts/side/gen_next/M261101-hongsi-img.json / -vid.json (제작 때 scripts/side/gen/ 로 옮겨 실행)."}$q$::jsonb || jsonb_build_object('at',now())) where id='P261031-grandma-hongsi';